function badgeCat(string $key,string $label):string{$tone='neutral';foreach([[['ticket','umrah','visa','hotel','transport','tour'],'teal'],[['payment_received','cash_received','bank_received'],'green'],[['payment_paid','cash_paid','bank_paid','other_debit'],'orange'],[['refund'],'violet'],[['adjustment'],'slate']] as [$keys,$tn]){foreach($keys as $k)if(str_contains($key,$k)){$tone=$tn;break 2;}}return '<span class="chip chip-'.$tone.'">'.e($label).'</span>';}
function withFooterLimit(string $body,string $extra=''):string{
 $start=strpos($body,'<div class="listing-tools">');if($start===false)return $body;
 $end=strpos($body,'</form></div>',$start);if($end===false)return $body;$end+=13;
 $tools=substr($body,$start,$end-$start);if($extra!=='')$tools=str_replace('class="listing-tools"','class="listing-tools '.e($extra).'"',$tools);
 $body=substr_replace($body,'',$start,$end-$start);
 return str_replace('<nav class="pager" aria-label="Pagination">','<nav class="pager" aria-label="Pagination">'.$tools,$body);
}
// Render the ledger's final structure before the browser paints it.
function ledgerScreen(string $body):string{
 $entryStart=strpos($body,'<div class="card simple-entry noprint">');$drawer='';$hasEntry=$entryStart!==false;
 if($hasEntry){$entryEnd=strpos($body,'<div class="card statement-card">',$entryStart);
  if($entryEnd!==false){$entry=substr($body,$entryStart,$entryEnd-$entryStart);$body=substr_replace($body,'',$entryStart,$entryEnd-$entryStart);
   $drawer='<dialog class="form-drawer ledger-entry-drawer noprint" data-side="dr" aria-labelledby="entry-drawer-title"><div class="drawer-bar"><h2 id="entry-drawer-title">New debit entry</h2><button type="button" class="ghost" data-close-entry aria-label="Close transaction form">Close ×</button></div>'.$entry.'</dialog>';}}
 $management='';$managementStart=strpos($body,'<form method="post" class="noprint" style="margin-top:14px">');
 if($managementStart!==false){$managementEnd=strpos($body,'</form>',$managementStart)+7;$management=substr($body,$managementStart,$managementEnd-$managementStart);$management=str_replace('class="noprint" style="margin-top:14px"','class="noprint workspace-management"',$management);$body=substr_replace($body,'',$managementStart,$managementEnd-$managementStart);}
 $headStart=strpos($body,'<div class="page-head">');$headEnd=$headStart===false?false:strpos($body,'<div class="simple-overview">',$headStart);
 if($headStart!==false&&$headEnd!==false){$head=substr($body,$headStart,$headEnd-$headStart);
  $head=preg_replace_callback('/<h1>(.*?)<\/h1>/s',static fn($m)=>'<h1><span class="ledger-identity" aria-hidden="true">'.e(strtoupper(substr(html_entity_decode(strip_tags($m[1]),ENT_QUOTES,'UTF-8'),0,1))).'</span>'.$m[1].'</h1>',$head,1);
  $head=str_replace(' · Complete transaction history, payments and outstanding balance','',$head);
  $buttons=$hasEntry?'<button type="button" class="btn transaction-action" data-open-drawer="dr" title="Record a debit transaction">+ Debit</button><button type="button" class="ghost transaction-action" data-open-drawer="cr" title="Record a credit transaction">+ Credit</button>':'';
  $head=str_replace('<div class="noprint row">','<div class="workspace-actions noprint">'.$buttons.'<div class="noprint row ledger-exports">',$head);
  $head=str_replace(' Print / PDF</a></div></div>',' Print / PDF</a></div>'.$management.'</div></div>',$head);
  $body=substr_replace($body,$head,$headStart,$headEnd-$headStart);
 }
 $body=withFooterLimit($body,'pagination-limit');
 $from=(string)($_GET['from']??'');$to=(string)($_GET['to']??'');$period=$from!==''||$to!==''?($from?:'Start').' → '.($to?:'Today'):'All transactions';
 $body=str_replace('<h3>Ledger Statement</h3><span class="muted">Dr / Cr · Running balance</span>','<h3>Transactions</h3><span class="ledger-period">'.e($period).'</span>',$body);
 $body=str_replace('class="filter noprint"','class="filter noprint" aria-label="Filter transactions by date"',$body);
 return $body.$drawer;
}
function agencyScreen(string $body):string{
 $start=strpos($body,'<div class="card" id="new-agency">');
 if($start===false)return $body;
 $end=strpos($body,'<div class="card table-card">',$start);if($end===false)return $body;
 $form=substr($body,$start,$end-$start);$body=substr_replace($body,'',$start,$end-$start);
 $body=str_replace('class="grid2 cards-grid"','class="grid2 cards-grid workspace-grid"',$body);
 $body=preg_replace('~<button type="button" class="btn btn-inline" data-scroll="#new-agency">.*?</button>~s','<div class="workspace-actions"><button type="button" class="btn btn-inline" data-open-drawer="new">+ New Agency</button></div>',$body,1);
 $body=withFooterLimit($body);
 return $body.'<dialog class="form-drawer noprint" aria-labelledby="agency-drawer-title"><div class="drawer-bar"><h2 id="agency-drawer-title">New agency</h2><button type="button" class="ghost" data-close-drawer>Close ×</button></div>'.$form.'</dialog>';
}
