function page(string $title,string $body,bool $shell=true){
 $u=me();$f=flash();tok();if(session_status()===PHP_SESSION_ACTIVE)session_write_close();$an=$u['an']??'';$cur=$_GET['p']??'';if($cur==='acc')$cur='accounts';
