 $nav='';$seen=[];foreach($navItems as [$key,$label,$icon]){if(isset($seen[$key]))continue;$seen[$key]=1;$nav.='<a href="?p='.$key.'"'.($cur===$key?' class="active" aria-current="page"':'').'><span class="nico">'.uiIcon($icon,'ui-ic').'</span><span>'.$label.'</span></a>';}
 $screen=(string)($_GET['p']??'');if($screen==='')$screen=$role==='master'?'agencies':'home';$bodyClass=$shell?'':'auth';
