  echo '<div class="layout"><header class="topbar"><button type="button" class="icon-btn menu-btn" data-menu aria-label="Toggle menu"><span></span><span></span><span></span></button><form class="top-search"><input type="hidden" name="p" value="'.$searchPage.'"><span class="ts-ico">'.uiIcon('search','ui-ic').'</span><input type="search" name="s" placeholder="'.e($searchLabel).'" aria-label="Search" value="'.e((string)($_GET['s']??'')).'"></form><div class="top-actions">' .($role!=='master'?'<a class="support-top" href="'.e(supportLink()).'" target="_blank" rel="noopener noreferrer" data-support-open aria-label="Help and support"><span aria-hidden="true">?</span> Help</a>':'').'<button type="button" class="chat-top icon-btn" data-chat-open aria-label="'.($role==='master'?'Open agency messages':'Chat with master admin').'" title="Messages">'.chatIcon().'<span class="chat-badge" data-chat-badge hidden></span></button><a class="icon-btn top-search-shortcut" href="?p='.$searchPage.'" title="Search">'.uiIcon('search','ui-ic').'</a><a class="user-chip" href="?p=profile"><span class="avatar">'.$init.'</span><span class="uc-text"><b>'.$name.'</b><small>'.$who.'</small></span></a></div></header><main class="content">';
 } else echo '<main class="content">';
 if($f)echo '<div class="flash" role="status">'.e($f).'</div>';
 if(!$shell){$support='<div class="auth-support"><div><strong>Need a hand?</strong><span>Login issues or questions? I can help.</span></div><a href="'.e(supportLink()).'" target="_blank" rel="noopener noreferrer" data-support-open>Get help ↗</a><div class="auth-support-direct"><a href="'.e(supportLink()).'" target="_blank" rel="noopener noreferrer">WhatsApp: 03476942833</a><a href="mailto:abusidique555@gmail.com">abusidique555@gmail.com</a></div>'.developerCredit().'</div>';$pos=strrpos($body,'</div></div>');if($pos!==false)$body=substr_replace($body,$support,$pos,0);}
