function ledgerCatOptions(array $cats):string{$out='';foreach($cats as $key=>$label)$out.='<option value="'.e($key).'">'.e($label).'</option>';return $out;}
function sel(array $o,string $n,string $c=''){$r='<select name="'.$n.'">';foreach($o as $k=>$v)$r.='<option value="'.e($k).'"'.((string)$k===$c?' selected':'').'>'.e($v).'</option>';return $r.'</select>';}
function statCards(array $items):string{$o='<div class="stats">';foreach($items as [$ic,$label,$value,$tone]){$o.='<div class="card stat"><span class="stat-ic tone-'.$tone.'">'.uiIcon($ic).'</span><span class="stat-t"><b>'.e((string)$value).'</b><small>'.e($label).'</small></span></div>';}return $o.'</div>';}
function pieSvg(array $parts,int $size=176,string $hole='#fff'):string{$tot=array_sum(array_column($parts,'value'));$cx=$size/2;$cy=$size/2;$r=$size/2-6;$ring='';$wid=$size>=170?20:14;
 if($tot<=0)return '<div class="ring-empty">No entries yet</div>';
 $off=-90;foreach($parts as $p){$v=(float)$p['value'];if($v<=0)continue;$len=$v/$tot*360;$mid=$off+$len/2;$ring.='<circle cx="'.$cx.'" cy="'.$cy.'" r="'.$r.'" fill="none" stroke="'.$p['color'].'" stroke-width="'.$wid.'" stroke-dasharray="'.round($len/360*2*M_PI*$r,2).' '.round(2*M_PI*$r,2).'" transform="rotate('.round($off,2).' '.$cx.' '.$cy.')"/>';if($len>=18){$lx=round($cx+cos(deg2rad($mid))*($r-1),1);$ly=round($cy+sin(deg2rad($mid))*($r-1)+3.5,1);$ring.='<text x="'.$lx.'" y="'.$ly.'" text-anchor="middle" font-size="10" font-weight="800" fill="#fff">'.(int)$p['value'].'</text>';}$off+=$len;}
 return '<div class="donut-wrap"><svg class="donut" viewBox="0 0 '.$size.' '.$size.'" width="'.$size.'" height="'.$size.'" role="img" aria-label="Distribution">'.$ring.'<circle cx="'.$cx.'" cy="'.$cy.'" r="'.round($r-$wid/2-2,2).'" fill="'.$hole.'"/><text x="'.$cx.'" y="'.($cy-2).'" text-anchor="middle" font-size="21" font-weight="800" fill="#141a24">'.number_format((int)$tot).'</text><text x="'.$cx.'" y="'.($cy+14).'" text-anchor="middle" font-size="9" fill="#6c7a8a">TOTAL</text></svg></div>';}
function pieLegend(array $parts):string{$tot=array_sum(array_column($parts,'value'));$o='<ul class="legend">';foreach($parts as $p){$o.='<li><i style="background:'.e($p['color']).'"></i><span>'.e($p['label']).'</span><b>'.(int)$p['value'].'</b><small>'.($tot>0?round($p['value']/$tot*100):0).'%</small></li>';}return $o.'</ul>';}
function shortMoney(int $v):string{if($v>=1000000000)return round($v/1000000000,1).' Cr';if($v>=10000000)return round($v/10000000,1).' L';if($v>=100000)return round($v/100000,1).'k';return rtrim(rtrim(moneyDecimal($v),'0'),'.');}
function barsSvg(array $rows,string $c1='#1f52b5',string $c2='#c9d9f5'):string{$max=0;foreach($rows as $r)$max=max($max,(int)$r[1],(int)$r[2]);$w=760;$h=260;$padL=56;$padR=8;$padB=28;$padT=16;$plot=$h-$padB-$padT;$bw=14;$step=($w-$padL-$padR)/max(1,count($rows));
 $grid='';for($i=0;$i<=4;$i++){$y=$padT+$plot/4*$i;$grid.='<line x1="'.$padL.'" y1="'.round($y,1).'" x2="'.($w-$padR).'" y2="'.round($y,1).'" stroke="#e3e8f0" stroke-width="1"/>';$val=(int)round($max*(4-$i)/4);$grid.='<text x="'.($padL-10).'" y="'.round($y+3.5,1).'" text-anchor="end" font-size="10" fill="#8a9ab2">'.($max?shortMoney($val):'0').'</text>';}
 $bars='';foreach($rows as $i=>$row){$lab=$row[0];$d=(int)$row[1];$c=(int)$row[2];$x=$padL+$step*$i+$step/2;$hd=($max&&$d)?max(2,$plot*$d/$max):0;$hc=($max&&$c)?max(2,$plot*$c/$max):0;
  $bars.='<g class="bar-group"><rect x="'.round($x-$bw-1,1).'" y="'.round($padT+$plot-$hd,1).'" width="'.$bw.'" height="'.round($hd,1).'" rx="4" fill="'.$c1.'"/>';
  $bars.='<rect x="'.round($x+1,1).'" y="'.round($padT+$plot-$hc,1).'" width="'.$bw.'" height="'.round($hc,1).'" rx="4" fill="'.$c2.'"/>';
  $bars.='<text x="'.round($x,1).'" y="'.($h-8).'" text-anchor="middle" font-size="10.5" fill="#7d8ba3">'.e($lab).'</text>';
  if($d>0)$bars.='<text x="'.round($x-$bw/2-1,1).'" y="'.round($padT+$plot-$hd-5,1).'" text-anchor="middle" font-size="8.5" fill="#4f6a8f">'.shortMoney($d).'</text>';
  if($c>0)$bars.='<text x="'.round($x+1+$bw/2,1).'" y="'.round($padT+$plot-$hc-5,1).'" text-anchor="middle" font-size="8.5" fill="#9aaed4">'.shortMoney($c).'</text>';
  $bars.='</g>';}
 return '<svg class="barchart" viewBox="0 0 '.$w.' '.$h.'" role="img" aria-label="Monthly Debit and Credit chart">'.$grid.'<line x1="'.$padL.'" y1="'.($padT+$plot).'" x2="'.($w-$padR).'" y2="'.($padT+$plot).'" stroke="#d5dae2"/>'.$bars.'</svg>';}
